"s_s_spiegel_kein_offline":["%s: Weder %s noch %s ist ein Offline-Konto – Kontor kann nichts spiegeln.", "%s: neither %s nor %s is an offline account – Kontor cannot mirror anything."],
"s_s_spiegel_original_weg":["%s: Die gespiegelte Buchung vom %s über %s hat kein Original mehr in %s – bitte auch in %s löschen.", "%s: the mirrored booking of %s for %s has no original in %s any more – please delete it in %s too."],
"s_s_spiegel_geaendert":["%s: Die gespiegelte Buchung vom %s über %s passt nicht mehr zum Original in %s (%s, %s) – bitte anpassen.", "%s: the mirrored booking of %s for %s no longer matches the original in %s (%s, %s) – please adjust it."],
